css:
:scope { width: min(100%, 1355px); margin-inline: auto; }
.gx { display: grid; grid-template-columns: repeat(24, minmax(0, 1fr)); grid-auto-rows: minmax(8px, auto); column-gap: 0; }
.gx__i { position: relative; z-index: 1; margin: 0; min-width: 0; overflow-wrap: break-word; }
.gx__i p { margin: 0; }
.gx__p { z-index: 0; }
.gx__img picture, .gx__img img { display: block; width: 100%; height: 100%; object-fit: cover; }
.gx__i1 { grid-column: 1 / span 2; grid-row: 1 / span 3; font-family: var(--os-font-label); font-size: 13.7px; font-weight: 700; line-height: 1.55; letter-spacing: 0.22em; text-transform: uppercase; color: var(--os-color-link); }
.gx__i2 { grid-column: 1 / span 17; grid-row: 5 / span 8; font-family: var(--os-font-heading); font-size: 59.5px; font-weight: 700; line-height: 1.02; letter-spacing: -0.02em; color: var(--os-color-heading); }
.gx__i3 { grid-column: 1 / span 14; grid-row: 18 / span 11; font-family: var(--os-font-body); font-size: 23.6px; font-weight: 400; line-height: 1.37; letter-spacing: 0em; color: var(--os-color-heading); }
.gx__i4 { grid-column: 16 / span 5; grid-row: 18 / span 3; font-family: var(--os-font-label); font-size: 13.7px; font-weight: 700; line-height: 1; letter-spacing: 0.18em; text-transform: uppercase; color: var(--os-color-surface); }
.gx__i5 { grid-column: 16 / span 9; grid-row: 22 / span 22; font-family: var(--os-font-body); font-size: 19.7px; font-weight: 400; line-height: 1.25; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i6 { grid-column: 1 / span 7; grid-row: 32 / span 20; font-family: var(--os-font-body); font-size: 19.7px; font-weight: 400; line-height: 1.38; letter-spacing: 0em; color: var(--os-color-heading); }
.gx__i7 { grid-column: 1 / span 14; grid-row: 32 / span 32; font-family: var(--os-font-body); font-size: 19.7px; font-weight: 400; line-height: 1.38; letter-spacing: 0em; color: var(--os-color-heading); }
.gx__i8 { grid-column: 8 / span 7; grid-row: 47 / span 17; font-family: var(--os-font-body); font-size: 19.7px; font-weight: 400; line-height: 1.38; letter-spacing: 0em; color: var(--os-color-heading); }
.gx__i9 { grid-column: 16 / span 9; grid-row: 47 / span 5; font-family: var(--os-font-label); font-size: 13.7px; font-weight: 700; line-height: 1; letter-spacing: 0.18em; text-transform: uppercase; color: var(--os-color-surface); }
.gx__i10 { grid-column: 16 / span 9; grid-row: 53 / span 10; font-family: var(--os-font-body); font-size: 19.7px; font-weight: 400; line-height: 1.38; letter-spacing: 0em; font-style: italic; color: var(--os-color-heading); }
.gx__i11 { grid-column: 16 / span 9; grid-row: 64 / span 10; font-family: var(--os-font-body); font-size: 19.7px; font-weight: 700; line-height: 1.38; letter-spacing: 0em; font-style: italic; color: var(--os-color-heading); }
.gx__i12 { grid-column: 1 / span 4; grid-row: 68 / span 7; font-family: var(--os-font-label); font-size: 13.7px; font-weight: 700; line-height: 1.55; letter-spacing: 0.2em; text-transform: uppercase; color: var(--os-color-heading); }
.gx__i13 { grid-column: 4 / span 5; grid-row: 68 / span 7; font-family: var(--os-font-label); font-size: 13.7px; font-weight: 700; line-height: 1.55; letter-spacing: 0.2em; text-transform: uppercase; color: var(--os-color-heading); }
.gx__i14 { grid-column: 10 / span 3; grid-row: 68 / span 7; font-family: var(--os-font-label); font-size: 13.7px; font-weight: 700; line-height: 1.55; letter-spacing: 0.2em; text-transform: uppercase; color: var(--os-color-heading); }
@media (max-width: 767px) {
  .gx { display: flex; flex-direction: column; gap: var(--os-space-sm); }
  .gx__i1 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i2 { font-family: var(--os-font-heading); font-size: 48px; }
  .gx__i3 { font-family: var(--os-font-body); font-size: 19px; }
  .gx__i4 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i5 { font-family: var(--os-font-body); font-size: 16px; }
  .gx__i6 { font-family: var(--os-font-body); font-size: 16px; }
  .gx__i7 { font-family: var(--os-font-body); font-size: 16px; }
  .gx__i8 { font-family: var(--os-font-body); font-size: 16px; }
  .gx__i9 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i10 { font-family: var(--os-font-body); font-size: 16px; }
  .gx__i11 { font-family: var(--os-font-body); font-size: 16px; }
  .gx__i12 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i13 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i14 { font-family: var(--os-font-label); font-size: 14px; }
}
